out.println("function MM_preloadImages() { //v3.0                                                                                                                                                                                                                                                                                                                                                                                                            ");
out.println("  var d=document; if(d.images){ if(!d.MM_p) d.MM_p=new Array();                                                                                                                                                                                                                                                                                                                                                                                 ");
out.println("    var i,j=d.MM_p.length,a=MM_preloadImages.arguments; for(i=0; i<a.length; i++)                                                                                                                                                                                                                                                                                                                                                               ");
